window.SYLLABUS = {"versions":[{"id":"2026-2028","label":"2026–2028","topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"n":"1","text":"Describe the characteristics of living organisms by describing:\n(a) \u0007movement as an action by an organism or part of an organism causing a change of position or place\n(b) \u0007respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n(c) \u0007sensitivity as the ability to detect and respond to changes in the internal or external environment\n(d) \u0007growth as a permanent increase in size and dry mass\n(e) \u0007reproduction as the processes that make more of the same kind of organism\n(f) \u0007excretion as the removal of the waste products of metabolism and substances in excess of requirements\n(g) \u0007nutrition as the taking in of materials for energy, growth and development"}],"supplement":[]},{"n":"1.2","title":"Concept and uses of classification systems","core":[{"n":"1","text":"State that organisms can be classified into groups by the features that they share"},{"n":"2","text":"Describe a species as a group of organisms that can reproduce to produce fertile offspring"},{"n":"3","text":"Describe the binomial system of naming species as an internationally agreed system in which the scientiﬁc name of an organism is made up of two parts showing the genus and species"},{"n":"4","text":"Construct and use dichotomous keys based on identifiable features"}],"supplement":[{"n":"5","text":"Explain that classiﬁcation systems aim to reﬂect evolutionary relationships"},{"n":"6","text":"Explain that the sequences of bases in DNA are used as a means of classiﬁcation"},{"n":"7","text":"Explain that groups of organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"n":"1","text":"\u0007State the main features used to place animals and plants into the appropriate kingdoms"},{"n":"2","text":"\u0007State the main features used to place organisms into groups within the animal kingdom, limited to:\n(a) \u0007the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish\n(b) \u0007the main groups of arthropods: myriapods, insects, arachnids, crustaceans"},{"n":"3","text":"\u0007Classify organisms using the features identified in 1.3.1 and 1.3.2"}],"supplement":[{"n":"4","text":"\u0007State the main features used to place all organisms into one of the five kingdoms: animal, plant, fungus, prokaryote, protoctist"},{"n":"5","text":"\u0007State the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"n":"6","text":"\u0007Classify organisms using the features identified in 1.3.4 and 1.3.5"},{"n":"7","text":"\u0007State the features of viruses, limited to a protein coat and genetic material"}]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure","core":[{"n":"1","text":"\u0007Describe and compare the structure of a plant cell with an animal cell, limited to: cell wall, cell membrane, nucleus, cytoplasm, chloroplasts, ribosomes, mitochondria, vacuoles"},{"n":"2","text":"\u0007Describe the structure of a bacterial cell, limited to: cell wall, cell membrane, cytoplasm, ribosomes, circular DNA, plasmids"},{"n":"3","text":"\u0007Identify the cell structures listed in 2.1.1 and 2.1.2 in diagrams and images of plant, animal and bacterial cells"},{"n":"4","text":"\u0007Describe the functions of the structures listed in 2.1.1 and 2.1.2 in plant, animal and bacterial cells"},{"n":"5","text":"\u0007State that new cells are produced by division of existing cells"},{"n":"6","text":"\u0007State that specialised cells have specific functions, limited to:\n(a) \u0007ciliated cells – movement of mucus in the trachea and bronchi\n(b) root hair cells – absorption\n(c) palisade mesophyll cells – photosynthesis\n(d) \u0007neurones – conduction of electrical impulses\n(e) red blood cells – transport of oxygen\n(f) \u0007sperm and egg cells (gametes) – reproduction"},{"n":"7","text":"\u0007Describe the meaning of the terms: cell, tissue, organ, organ system and organism as illustrated by examples given in the syllabus"}],"supplement":[]},{"n":"2.2","title":"Size of specimens","core":[{"n":"1","text":"State and use the formula: magnification = image size ÷ actual size"},{"n":"2","text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"n":"3","text":"Convert measurements between millimetres (mm) and micrometres (μm)"}]}]},{"n":"3","title":"Movement into and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"n":"1","text":"Describe diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration (i.e. down a concentration gradient), as a result of their random movement"},{"n":"2","text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"n":"3","text":"State that some substances move into and out of cells by diffusion through the cell membrane"},{"n":"4","text":"Describe the importance of diffusion of gases and solutes in living organisms"},{"n":"5","text":"Investigate the factors that influence diffusion, limited to: surface area, temperature, concentration gradient and distance"}],"supplement":[]},{"n":"3.2","title":"Osmosis","core":[{"n":"1","text":"Describe the role of water as a solvent in organisms with reference to digestion, excretion and transport"},{"n":"2","text":"State that water diffuses through partially permeable membranes by osmosis"},{"n":"3","text":"State that water moves into and out of cells by osmosis through the cell membrane"},{"n":"4","text":"Investigate osmosis using materials such as dialysis tubing"},{"n":"5","text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"n":"6","text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"n":"7","text":"Describe osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"n":"8","text":"Explain the effects on plant cells of immersing them in solutions of different concentrations by using the terms: turgid, turgor pressure, plasmolysis, flaccid"},{"n":"9","text":"Explain the importance of water potential and osmosis in the uptake and loss of water by organisms"}]},{"n":"3.3","title":"Active transport","core":[{"n":"1","text":"Describe active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration (i.e. against a concentration gradient), using energy from respiration"}],"supplement":[{"n":"2","text":"Explain the importance of active transport as a process for movement of molecules or ions across membranes, including ion uptake by root hairs"},{"n":"3","text":"State that protein carriers move molecules or ions across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4.1","title":"Biological molecules","core":[{"n":"1","text":"List the chemical elements that make up: carbohydrates, fats and proteins"},{"n":"2","text":"State that large molecules are made from smaller molecules, limited to:\n(a) starch, glycogen and cellulose from glucose\n(b) proteins from amino acids\n(c) fats and oils from fatty acids and glycerol"},{"n":"3","text":"Describe the use of:\n(a) iodine solution test for starch\n(b) Benedict’s solution test for reducing sugars\n(c) biuret test for proteins\n(d) ethanol emulsion test for fats and oils\n(e) DCPIP test for vitamin C"}],"supplement":[{"n":"4","text":"Describe the structure of a DNA molecule:\n(a) \u0007two strands coiled together to form a double helix\n(b) \u0007each strand contains chemicals called bases\n(c) \u0007bonds between pairs of bases hold the strands together\n(d) \u0007the bases always pair up in the same way: A with T, and C with G (full names are not required)"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5.1","title":"Enzymes","core":[{"n":"1","text":"Describe a catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"n":"2","text":"Describe enzymes as proteins that are involved in all metabolic reactions, where they function as biological catalysts"},{"n":"3","text":"Describe why enzymes are important in all living organisms in terms of a reaction rate necessary to sustain life"},{"n":"4","text":"Describe enzyme action with reference to the shape of the active site of an enzyme being complementary to its substrate and the formation of products"},{"n":"5","text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity with reference to optimum temperature and denaturation"}],"supplement":[{"n":"6","text":"Explain enzyme action with reference to: active site, enzyme-substrate complex, substrate and product"},{"n":"7","text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"n":"8","text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"n":"9","text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"n":"1","text":"Describe photosynthesis as the process by which plants synthesise carbohydrates from raw materials using energy from light"},{"n":"2","text":"State the word equation for photosynthesis as: carbon dioxide + water → glucose + oxygen in the presence of light and chlorophyll"},{"n":"3","text":"State that chlorophyll is a green pigment that is found in chloroplasts"},{"n":"4","text":"State that chlorophyll transfers energy from light into energy in chemicals, for the synthesis of carbohydrates"},{"n":"5","text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis, limited to:\n(a) starch as an energy store\n(b) cellulose to build cell walls\n(c) \u0007glucose used in respiration to provide energy\n(d) sucrose for transport in the phloem\n(e) nectar to attract insects for pollination"},{"n":"6","text":"Explain the importance of:\n(a) nitrate ions for making amino acids\n(b) magnesium ions for making chlorophyll"},{"n":"7","text":"Investigate the need for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"n":"8","text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis"},{"n":"9","text":"Investigate and describe the effect of light and dark conditions on gas exchange in an aquatic plant using hydrogencarbonate indicator solution"}],"supplement":[{"n":"10","text":"State the balanced chemical equation for photosynthesis as: 6CO2 + 6H2O → C6H12O6 + 6O2"},{"n":"11","text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"}]},{"n":"6.2","title":"Leaf structure","core":[{"n":"1","text":"State that most leaves have a large surface area and are thin, and explain how these features are adaptations for photosynthesis"},{"n":"2","text":"Identify in diagrams and images the following structures in the leaf of a dicotyledonous plant: chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, air spaces, vascular bundles, xylem and phloem"},{"n":"3","text":"Explain how the structures listed in 6.2.2 adapt leaves for photosynthesis"}],"supplement":[]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"n":"1","text":"Describe what is meant by a balanced diet"},{"n":"2","text":"State the principal dietary sources and describe the importance of:\n(a) carbohydrates\n(b) fats and oils\n(c) proteins\n(d) vitamins, limited to C and D\n(e) mineral ions, limited to calcium and iron\n(f) fibre (roughage)\n(g) water"},{"n":"3","text":"State the causes of scurvy and rickets"}],"supplement":[]},{"n":"7.2","title":"Digestive system","core":[{"n":"1","text":"Identify in diagrams and images the main organs of the digestive system, limited to:\n(a) \u0007alimentary canal: mouth, oesophagus, stomach, small intestine (duodenum and ileum) and large intestine (colon, rectum, anus)\n(b) \u0007associated organs: salivary glands, pancreas, liver and gall bladder"},{"n":"2","text":"Describe the functions of the organs of the digestive system listed in 7.2.1, in relation to:\n(a) \u0007ingestion – the taking of substances, e.g. food and drink, into the body\n(b) digestion – the breakdown of food\n(c) \u0007absorption – the movement of nutrients from the intestines into the blood\n(d) \u0007assimilation – uptake and use of nutrients by cells\n(e) \u0007egestion – the removal of undigested food from the body as faeces"}],"supplement":[]},{"n":"7.3","title":"Physical digestion","core":[{"n":"1","text":"Describe physical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"n":"2","text":"State that physical digestion increases the surface area of food for the action of enzymes in chemical digestion"},{"n":"3","text":"Identify in diagrams and images the types of human teeth: incisors, canines, premolars and molars"},{"n":"4","text":"Describe the structure of human teeth, limited to: enamel, dentine, pulp, nerves, blood vessels and cement, and understand that teeth are embedded in bone and the gums"},{"n":"5","text":"Describe the functions of the types of human teeth in physical digestion of food"},{"n":"6","text":"Describe the function of the stomach in physical digestion"}],"supplement":[{"n":"7","text":"Outline the role of bile in emulsifying fats and oils to increase the surface area for chemical digestion"}]},{"n":"7.4","title":"Chemical digestion","core":[{"n":"1","text":"Describe chemical digestion as the breakdown of large insoluble molecules into small soluble molecules"},{"n":"2","text":"State the role of chemical digestion in producing small soluble molecules that can be absorbed"},{"n":"3","text":"Describe the functions of enzymes as follows:\n(a) \u0007amylase breaks down starch to simple reducing sugars\n(b) \u0007proteases break down protein to amino acids\n(c) \u0007lipase breaks down fats and oils to fatty acids and glycerol"},{"n":"4","text":"State where, in the digestive system, amylase, protease and lipase are secreted and where they act"},{"n":"5","text":"Describe the functions of hydrochloric acid in gastric juice, limited to killing harmful microorganisms in food and providing an acidic pH for optimum enzyme activity"}],"supplement":[{"n":"6","text":"Describe the digestion of starch in the digestive system:\n(a) amylase breaks down starch to maltose\n(b) \u0007maltase breaks down maltose to glucose on the membranes of the epithelium lining the small intestine"},{"n":"7","text":"Describe the digestion of protein by proteases in the digestive system:\n(a) \u0007pepsin breaks down protein in the acidic conditions of the stomach\n(b) \u0007trypsin breaks down protein in the alkaline conditions of the small intestine"},{"n":"8","text":"Explain that bile is an alkaline mixture that neutralises the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"}]},{"n":"7.5","title":"Absorption","core":[{"n":"1","text":"State that the small intestine is the region where nutrients are absorbed"},{"n":"2","text":"State that most water is absorbed from the small intestine but that some is also absorbed from the colon"}],"supplement":[{"n":"3","text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"n":"4","text":"Describe the structure of a villus"},{"n":"5","text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Xylem and phloem","core":[{"n":"1","text":"State the functions of xylem and phloem:\n(a) \u0007xylem – transport of water and mineral ions, and support\n(b) \u0007phloem – transport of sucrose and amino acids"},{"n":"2","text":"Identify in diagrams and images the position of xylem and phloem as seen in sections of roots, stems and leaves of non-woody dicotyledonous plants"}],"supplement":[{"n":"3","text":"Relate the structure of xylem vessels to their function, limited to:\n(a) \u0007thick walls with lignin (details of lignification are not required)\n(b) no cell contents\n(c) \u0007cells joined end to end with no cross walls to form a long continuous tube"}]},{"n":"8.2","title":"Water uptake","core":[{"n":"1","text":"Identify in diagrams and images root hair cells and state their functions"},{"n":"2","text":"State that the large surface area of root hairs increases the uptake of water and mineral ions"},{"n":"3","text":"Outline the pathway taken by water through the root, stem and leaf as: root hair cells, root cortex cells, xylem, mesophyll cells"},{"n":"4","text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[]},{"n":"8.3","title":"Transpiration","core":[{"n":"1","text":"Describe transpiration as the loss of water vapour from leaves"},{"n":"2","text":"State that water evaporates from the surfaces of the mesophyll cells into the air spaces and then diffuses out of the leaves through the stomata as water vapour"},{"n":"3","text":"Investigate and describe the effects of variation of temperature and wind speed on transpiration rate"}],"supplement":[{"n":"4","text":"Explain how water vapour loss is related to: the large internal surface area provided by the interconnecting air spaces between mesophyll cells and the size and number of stomata"},{"n":"5","text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by forces of attraction between water molecules"},{"n":"6","text":"Explain the effects on the rate of transpiration of varying the following factors: temperature, wind speed and humidity"},{"n":"7","text":"Explain how and why wilting occurs"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"n":"1","text":"Describe translocation as the movement of sucrose and amino acids in phloem from sources to sinks"},{"n":"2","text":"Describe:\n(a) \u0007sources as the parts of plants that release sucrose or amino acids\n(b) \u0007sinks as the parts of plants that use or store sucrose or amino acids"},{"n":"3","text":"Explain why some parts of a plant may act as a source and a sink at different times"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Circulatory systems","core":[{"n":"1","text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"n":"2","text":"Describe the single circulation of a fish"},{"n":"3","text":"Describe the double circulation of a mammal"},{"n":"4","text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"n":"1","text":"Identify in diagrams and images the structures of the mammalian heart, limited to: muscular wall, septum, left and right ventricles, left and right atria, one-way valves and coronary arteries"},{"n":"2","text":"State that blood is pumped away from the heart in arteries and returns to the heart in veins"},{"n":"3","text":"State that the activity of the heart may be monitored by: ECG, pulse rate and listening to sounds of valves closing"},{"n":"4","text":"Investigate and describe the effect of physical activity on the heart rate"},{"n":"5","text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors including: diet, lack of exercise, stress, smoking, genetic predisposition, age and sex"},{"n":"6","text":"Discuss the roles of diet and exercise in reducing the risk of coronary heart disease"}],"supplement":[{"n":"7","text":"Identify in diagrams and images the atrioventricular and semilunar valves in the mammalian heart"},{"n":"8","text":"Explain the relative thickness of:\n(a) \u0007the muscle walls of the left and right ventricles\n(b) \u0007the muscle walls of the atria compared to those of the ventricles"},{"n":"9","text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"n":"10","text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"n":"11","text":"Explain the effect of physical activity on the heart rate"}]},{"n":"9.3","title":"Blood vessels","core":[{"n":"1","text":"Describe the structure of arteries, veins and capillaries, limited to: relative thickness of wall, diameter of the lumen and the presence of valves in veins"},{"n":"2","text":"State the functions of capillaries"},{"n":"3","text":"Identify in diagrams and images the main blood vessels to and from the:\n(a) \u0007heart, limited to: vena cava, aorta, pulmonary artery and pulmonary vein\n(b) \u0007lungs, limited to: pulmonary artery and pulmonary vein\n(c) kidney, limited to: renal artery and renal vein"}],"supplement":[{"n":"4","text":"Explain how the structure of arteries and veins is related to the pressure of the blood that they transport"},{"n":"5","text":"Explain how the structure of capillaries is related to their functions"},{"n":"6","text":"Identify, in diagrams and images, the main blood vessels to and from the liver as: hepatic artery, hepatic veins and hepatic portal vein"}]},{"n":"9.4","title":"Blood","core":[{"n":"1","text":"List the components of blood as: red blood cells, white blood cells, platelets and plasma"},{"n":"2","text":"Identify red and white blood cells in photomicrographs and diagrams"},{"n":"3","text":"State the functions of the following components of blood:\n(a) \u0007red blood cells in transporting oxygen, including the role of haemoglobin\n(b) \u0007white blood cells in phagocytosis and antibody production\n(c) platelets in clotting (details are not required)\n(d) \u0007plasma in the transport of blood cells, ions, nutrients, urea, hormones and carbon dioxide"},{"n":"4","text":"State the roles of blood clotting as preventing blood loss and the entry of pathogens"}],"supplement":[{"n":"5","text":"Identify lymphocytes and phagocytes in photomicrographs and diagrams"},{"n":"6","text":"State the functions of:\n(a) lymphocytes – antibody production\n(b) \u0007phagocytes – engulfing pathogens by phagocytosis"},{"n":"7","text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10.1","title":"Diseases and immunity","core":[{"n":"1","text":"Describe a pathogen as a disease-causing organism"},{"n":"2","text":"Describe a transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"n":"3","text":"State that a pathogen is transmitted:\n(a) \u0007by direct contact, including through blood and other body fluids\n(b) \u0007indirectly, including from contaminated surfaces, food, animals and air"},{"n":"4","text":"Describe the body defences, limited to: skin, hairs in the nose, mucus, stomach acid and white blood cells"},{"n":"5","text":"Explain the importance of the following in controlling the spread of disease:\n(a) a clean water supply\n(b) hygienic food preparation\n(c) good personal hygiene\n(d) waste disposal\n(e) \u0007sewage treatment (details of the stages of sewage treatment are not required)"}],"supplement":[{"n":"6","text":"Describe active immunity as defence against a pathogen by antibody production in the body"},{"n":"7","text":"State that each pathogen has its own antigens, which have specific shapes"},{"n":"8","text":"Describe antibodies as proteins that bind to antigens leading to direct destruction of pathogens or marking of pathogens for destruction by phagocytes"},{"n":"9","text":"State that specific antibodies have complementary shapes which fit specific antigens"},{"n":"10","text":"Explain that active immunity is gained after an infection by a pathogen or by vaccination"},{"n":"11","text":"Outline the process of vaccination:\n(a) \u0007weakened pathogens or their antigens are put into the body\n(b) \u0007the antigens stimulate an immune response by lymphocytes which produce antibodies\n(c) \u0007memory cells are produced that give long-term immunity"},{"n":"12","text":"Explain the role of vaccination in controlling the spread of diseases"},{"n":"13","text":"Explain that passive immunity is a short-term defence against a pathogen by antibodies acquired from another individual, including across the placenta and in breast milk"},{"n":"14","text":"Explain the importance of breast-feeding for the development of passive immunity in infants"},{"n":"15","text":"State that memory cells are not produced in passive immunity"},{"n":"16","text":"Describe cholera as a disease caused by a bacterium which is transmitted in contaminated water"},{"n":"17","text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of ions from the blood"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11.1","title":"Gas exchange in humans","core":[{"n":"1","text":"Describe the features of gas exchange surfaces in humans, limited to: large surface area, thin surface, good blood supply and good ventilation with air"},{"n":"2","text":"Identify in diagrams and images the following parts of the breathing system: lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"n":"3","text":"Investigate the differences in composition between inspired and expired air using limewater as a test for carbon dioxide"},{"n":"4","text":"Describe the differences in composition between inspired and expired air, limited to: oxygen, carbon dioxide and water vapour"},{"n":"5","text":"Investigate and describe the effects of physical activity on the rate and depth of breathing"}],"supplement":[{"n":"6","text":"Identify in diagrams and images the internal and external intercostal muscles"},{"n":"7","text":"State the function of cartilage in the trachea"},{"n":"8","text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"n":"9","text":"Explain the differences in composition between inspired and expired air"},{"n":"10","text":"Explain the link between physical activity and the rate and depth of breathing in terms of: an increased carbon dioxide concentration in the blood, which is detected by the brain, leading to an increased rate and greater depth of breathing"},{"n":"11","text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the breathing system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"n":"1","text":"State the uses of energy in living organisms, including: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"n":"2","text":"Investigate and describe the effect of temperature on respiration in yeast"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"n":"1","text":"Describe aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"n":"2","text":"State the word equation for aerobic respiration as: glucose + oxygen → carbon dioxide + water"}],"supplement":[{"n":"3","text":"State the balanced chemical equation for aerobic respiration as: C6H12O6 + 6O2 → 6CO2 + 6H2O"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"n":"1","text":"Describe anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"n":"2","text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"},{"n":"3","text":"State the word equation for anaerobic respiration in yeast as: glucose → alcohol + carbon dioxide"},{"n":"4","text":"State the word equation for anaerobic respiration in muscles during vigorous exercise as: glucose → lactic acid"}],"supplement":[{"n":"5","text":"State the balanced chemical equation for anaerobic respiration in yeast as: C6H12O6 → 2C2H5OH + 2CO2"},{"n":"6","text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"n":"7","text":"Outline how the oxygen debt is removed after exercise, limited to:\n(a) \u0007continuation of fast heart rate to transport lactic acid in the blood from the muscles to the liver\n(b) \u0007continuation of deeper and faster breathing to supply oxygen for aerobic respiration of lactic acid\n(c) aerobic respiration of lactic acid in the liver"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13.1","title":"Excretion in humans","core":[{"n":"1","text":"State that carbon dioxide is excreted through the lungs"},{"n":"2","text":"State that the kidneys excrete urea and excess water and ions"},{"n":"3","text":"Identify in diagrams and images the kidneys, ureters, bladder and urethra"}],"supplement":[{"n":"4","text":"Identify in diagrams and images the structure of the kidney, limited to the cortex and medulla"},{"n":"5","text":"Outline the structure and function of a nephron and its associated blood vessels, limited to:\n(a) \u0007the role of the glomerulus in the filtration from the blood of water, glucose, urea and ions\n(b) \u0007the role of the nephron in the reabsorption of all of the glucose, some of the ions and most of the water back into the blood\n(c) \u0007the formation of urine containing urea, excess water and excess ions (details of these processes are not required)"},{"n":"6","text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins"},{"n":"7","text":"State that urea is formed in the liver from excess amino acids"},{"n":"8","text":"Describe deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"n":"9","text":"Explain the importance of excretion, limited to toxicity of urea"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Coordination and response","core":[{"n":"1","text":"State that electrical impulses travel along neurones"},{"n":"2","text":"Describe the mammalian nervous system in terms of:\n(a) \u0007the central nervous system (CNS) consisting of the brain and the spinal cord\n(b) \u0007the peripheral nervous system (PNS) consisting of the nerves outside of the brain and spinal cord"},{"n":"3","text":"Describe the role of the nervous system as coordination and regulation of body functions"},{"n":"4","text":"Identify in diagrams and images sensory, relay and motor neurones"},{"n":"5","text":"Describe a simple reflex arc in terms of: receptor, sensory neurone, relay neurone, motor neurone and effector"},{"n":"6","text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"n":"7","text":"Describe a synapse as a junction between two neurones"}],"supplement":[{"n":"8","text":"Describe the structure of a synapse, including the presence of vesicles containing neurotransmitter molecules, the synaptic gap and receptor proteins"},{"n":"9","text":"Describe the events at a synapse as:\n(a) \u0007an impulse stimulates the release of neurotransmitter molecules from vesicles into the synaptic gap\n(b) \u0007the neurotransmitter molecules diffuse across the gap\n(c) \u0007neurotransmitter molecules bind with receptor proteins on the next neurone\n(d) \u0007an impulse is then stimulated in the next neurone"},{"n":"10","text":"State that synapses ensure that impulses travel in one direction only"}]},{"n":"14.2","title":"Sense organs","core":[{"n":"1","text":"Describe sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"n":"2","text":"Identify in diagrams and images the structures of the eye, limited to: cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"n":"3","text":"Describe the function of each part of the eye, limited to:\n(a) cornea – refracts light\n(b) \u0007iris – controls how much light enters the pupil\n(c) lens – focuses light on to the retina\n(d) \u0007retina – contains light receptors, some sensitive to light of different colours\n(e) optic nerve – carries impulses to the brain"},{"n":"4","text":"Explain the pupil reflex, limited to changes in light intensity and pupil diameter"}],"supplement":[{"n":"5","text":"Explain the pupil reflex in terms of the antagonistic action of circular and radial muscles in the iris"},{"n":"6","text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"n":"7","text":"Describe the distribution of rods and cones in the retina of a human"},{"n":"8","text":"Outline the function of rods and cones, limited to:\n(a) greater sensitivity of rods for night vision\n(b) \u0007three different kinds of cones, absorbing light of different colours, for colour vision"},{"n":"9","text":"Identify in diagrams and images the position of the fovea and state its function"}]},{"n":"14.3","title":"Hormones","core":[{"n":"1","text":"Describe a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"n":"2","text":"Identify in diagrams and images specific endocrine glands and state the hormones they secrete, limited to:\n(a) adrenal glands and adrenaline\n(b) pancreas and insulin\n(c) testes and testosterone\n(d) ovaries and oestrogen"},{"n":"3","text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to:\n(a) increased breathing rate\n(b) increased heart rate\n(c) increased pupil diameter"},{"n":"4","text":"Compare nervous and hormonal control, limited to speed of action and duration of effect"}],"supplement":[{"n":"5","text":"State that glucagon is secreted by the pancreas"},{"n":"6","text":"Describe the role of adrenaline in the control of metabolic activity, limited to:\n(a) \u0007increasing the blood glucose concentration\n(b) increasing heart rate"}]},{"n":"14.4","title":"Homeostasis","core":[{"n":"1","text":"Describe homeostasis as the maintenance of a constant internal environment"},{"n":"2","text":"State that insulin decreases blood glucose concentration"}],"supplement":[{"n":"3","text":"Explain the concept of homeostatic control by negative feedback with reference to a set point"},{"n":"4","text":"Describe the control of blood glucose concentration by the liver and the roles of insulin and glucagon"},{"n":"5","text":"Outline the treatment of Type 1 diabetes"},{"n":"6","text":"Identify in diagrams and images of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"n":"7","text":"Describe the maintenance of a constant internal body temperature in mammals in terms of: insulation, sweating, shivering and the role of the brain"},{"n":"8","text":"Describe the maintenance of a constant internal body temperature in mammals in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"n":"1","text":"Describe gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"n":"2","text":"Describe phototropism as a response in which parts of a plant grow towards or away from the direction of the light source"},{"n":"3","text":"Investigate and describe gravitropism and phototropism in shoots and roots"}],"supplement":[{"n":"4","text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"n":"5","text":"Explain the role of auxin in controlling shoot growth, limited to:\n(a) auxin is made in the shoot tip\n(b) \u0007auxin diffuses through the plant from the shoot tip\n(c) \u0007auxin is unequally distributed in response to light and gravity\n(d) auxin stimulates cell elongation"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"n":"1","text":"Describe a drug as any substance taken into the body that modifies or affects chemical reactions in the body"},{"n":"2","text":"Describe the use of antibiotics for the treatment of bacterial infections"},{"n":"3","text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"n":"4","text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"n":"5","text":"Explain how using antibiotics only when essential can limit the development of resistant bacteria such as MRSA"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"n":"1","text":"Describe asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"n":"2","text":"Identify examples of asexual reproduction in diagrams, images and information provided"}],"supplement":[{"n":"3","text":"Discuss the advantages and disadvantages of asexual reproduction:\n(a) to a population of a species in the wild\n(b) to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"n":"1","text":"Describe sexual reproduction as a process involving the fusion of the nuclei of two gametes to form a zygote and the production of offspring that are genetically different from each other"},{"n":"2","text":"Describe fertilisation as the fusion of the nuclei of gametes"}],"supplement":[{"n":"3","text":"State that nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"n":"4","text":"Discuss the advantages and disadvantages of sexual reproduction:\n(a) to a population of a species in the wild\n(b) to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"n":"1","text":"Identify in diagrams and images and draw the following parts of an insect-pollinated flower: sepals, petals, stamens, filaments, anthers, carpels, style, stigma, ovary and ovules"},{"n":"2","text":"State the functions of the structures listed in 16.3.1"},{"n":"3","text":"Identify in diagrams and images and describe the anthers and stigmas of a wind-pollinated flower"},{"n":"4","text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"n":"5","text":"Describe pollination as the transfer of pollen grains from an anther to a stigma"},{"n":"6","text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"n":"7","text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"n":"8","text":"Investigate and describe the environmental conditions that affect germination of seeds, limited to the requirement for: water, oxygen and a suitable temperature"}],"supplement":[{"n":"9","text":"Describe self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or a different flower on the same plant"},{"n":"10","text":"Describe cross-pollination as the transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"n":"11","text":"Discuss the potential effects of self-pollination and cross-pollination on a population, in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"n":"12","text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"n":"1","text":"Identify on diagrams and state the functions of the following parts of the male reproductive system: testes, scrotum, sperm ducts, prostate gland, urethra and penis"},{"n":"2","text":"Identify on diagrams and state the functions of the following parts of the female reproductive system: ovaries, oviducts, uterus, cervix and vagina"},{"n":"3","text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell)"},{"n":"4","text":"Explain the adaptive features of sperm, limited to: flagellum, mitochondria and enzymes in the acrosome"},{"n":"5","text":"Explain the adaptive features of egg cells, limited to: energy stores and the jelly coat that changes at fertilisation"},{"n":"6","text":"Compare male and female gametes in terms of: size, structure, motility and numbers"},{"n":"7","text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the lining of the uterus"},{"n":"8","text":"Identify on diagrams and state the functions of the following in the development of the fetus: umbilical cord, placenta, amniotic sac and amniotic fluid"}],"supplement":[{"n":"9","text":"Describe the function of the placenta and umbilical cord in relation to the exchange of dissolved nutrients, gases and excretory products between the blood of the mother and the blood of the fetus"},{"n":"10","text":"State that some pathogens and toxins can pass across the placenta and affect the fetus"}]},{"n":"16.5","title":"Sex hormones in humans","core":[{"n":"1","text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"n":"2","text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"n":"3","text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"n":"4","text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Sexually transmitted infections","core":[{"n":"1","text":"Describe a sexually transmitted infection (STI) as an infection that is transmitted through sexual contact"},{"n":"2","text":"State that human immunodeficiency virus (HIV) is a pathogen that causes an STI"},{"n":"3","text":"State that HIV infection may lead to AIDS"},{"n":"4","text":"Describe the methods of transmission of HIV"},{"n":"5","text":"Explain how the spread of STIs is controlled"}],"supplement":[]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Chromosomes, genes and proteins","core":[{"n":"1","text":"State that chromosomes are made of DNA, which contains genetic information in the form of genes"},{"n":"2","text":"Define a gene as a length of DNA that codes for a protein"},{"n":"3","text":"Define an allele as an alternative form of a gene"},{"n":"4","text":"Describe the inheritance of sex in humans with reference to X and Y chromosomes"}],"supplement":[{"n":"5","text":"State that the sequence of bases in a gene determines the sequence of amino acids used to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"n":"6","text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"n":"7","text":"Explain that DNA controls cell function by controlling the production of proteins, including enzymes, membrane carriers and receptors for neurotransmitters"},{"n":"8","text":"Explain how a protein is made, limited to: • the gene coding for the protein remains in the nucleus • messenger RNA (mRNA) is a copy of a gene • mRNA molecules are made in the nucleus and move to the cytoplasm • the mRNA passes through ribosomes • the ribosome assembles amino acids into protein molecules • the specific sequence of amino acids is determined by the sequence of bases in the mRNA \u0007(knowledge of the details of transcription or translation is not required)"},{"n":"9","text":"Explain that most body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs"},{"n":"10","text":"Describe a haploid nucleus as a nucleus containing a single set of chromosomes"},{"n":"11","text":"Describe a diploid nucleus as a nucleus containing two sets of chromosomes"},{"n":"12","text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.2","title":"Mitosis","core":[],"supplement":[{"n":"1","text":"Describe mitosis as nuclear division giving rise to genetically identical cells (details of the stages of mitosis are not required)"},{"n":"2","text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"},{"n":"3","text":"State that the exact replication of chromosomes occurs before mitosis"},{"n":"4","text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number in each daughter cell"},{"n":"5","text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.3","title":"Meiosis","core":[],"supplement":[{"n":"1","text":"State that meiosis is involved in the production of gametes"},{"n":"2","text":"Describe meiosis as a reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of the stages of meiosis are not required)"}]},{"n":"17.4","title":"Monohybrid inheritance","core":[{"n":"1","text":"Describe inheritance as the transmission of genetic information from generation to generation"},{"n":"2","text":"Describe genotype as the genetic make-up of an organism and in terms of the alleles present"},{"n":"3","text":"Describe phenotype as the observable features of an organism"},{"n":"4","text":"Describe homozygous as having two identical alleles of a particular gene"},{"n":"5","text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"n":"6","text":"Describe heterozygous as having two different alleles of a particular gene"},{"n":"7","text":"State that a heterozygous individual will not be pure-breeding"},{"n":"8","text":"Describe a dominant allele as an allele that is expressed if it is present in the genotype"},{"n":"9","text":"Describe a recessive allele as an allele that is only expressed when there is no dominant allele of the gene present in the genotype"},{"n":"10","text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"n":"11","text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1 : 1 and 3 : 1 ratios"},{"n":"12","text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"n":"13","text":"Explain how to use a test cross to identify an unknown genotype"},{"n":"14","text":"Describe codominance as a situation in which both alleles in heterozygous organisms contribute to the phenotype"},{"n":"15","text":"Explain the inheritance of ABO blood groups: phenotypes are A, B, AB and O blood groups and alleles are IA, IB and Io"},{"n":"16","text":"Describe a sex-linked characteristic as a feature in which the gene responsible is located on a sex chromosome and that this makes the characteristic more common in one sex than in the other"},{"n":"17","text":"Describe red-green colour blindness as an example of sex linkage"},{"n":"18","text":"Use genetic diagrams to predict the results of monohybrid crosses involving codominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"n":"1","text":"Describe variation as differences between individuals of the same species"},{"n":"2","text":"State that continuous variation results in a range of phenotypes between two extremes; examples include body length and body mass"},{"n":"3","text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates; examples include ABO blood groups, seed shape in peas and seed colour in peas"},{"n":"4","text":"State that discontinuous variation is usually caused by genes only and continuous variation is caused by both genes and the environment"},{"n":"5","text":"Investigate and describe examples of continuous and discontinuous variation"},{"n":"6","text":"Describe mutation as genetic change"},{"n":"7","text":"State that mutation is the way in which new alleles are formed"},{"n":"8","text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"n":"9","text":"Describe gene mutation as a random change in the base sequence of DNA"},{"n":"10","text":"State that mutation, meiosis, random mating and random fertilisation are sources of genetic variation in populations"}]},{"n":"18.2","title":"Adaptive features","core":[{"n":"1","text":"Describe an adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"n":"2","text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"n":"3","text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"n":"1","text":"Describe natural selection with reference to:\n(a) genetic variation within populations\n(b) production of many offspring\n(c) \u0007struggle for survival, including competition for resources\n(d) \u0007a greater chance of reproduction by individuals that are better adapted to the environment than others\n(e) \u0007these individuals pass on their alleles to the next generation"},{"n":"2","text":"Describe selective breeding with reference to:\n(a) \u0007selection by humans of individuals with desirable features\n(b) \u0007crossing these individuals to produce the next generation\n(c) \u0007selection of offspring showing the desirable features"},{"n":"3","text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals and apply this to given contexts"}],"supplement":[{"n":"4","text":"Describe adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"n":"5","text":"Describe the development of strains of antibiotic resistant bacteria as an example of natural selection"},{"n":"6","text":"Outline the differences between natural and artificial selection"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"n":"1","text":"State that the Sun is the principal source of energy input to biological systems"},{"n":"2","text":"Describe the flow of energy through living organisms, including light energy from the Sun and chemical energy in organisms, and its eventual transfer to the environment"}],"supplement":[]},{"n":"19.2","title":"Food chains and food webs","core":[{"n":"1","text":"Describe a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"n":"2","text":"Construct and interpret simple food chains"},{"n":"3","text":"Describe a food web as a network of interconnected food chains and interpret food webs"},{"n":"4","text":"Describe a producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"n":"5","text":"Describe a consumer as an organism that gets its energy by feeding on other organisms"},{"n":"6","text":"State that consumers may be classed as primary, secondary, tertiary and quaternary according to their position in a food chain"},{"n":"7","text":"Describe a herbivore as an animal that gets its energy by eating plants"},{"n":"8","text":"Describe a carnivore as an animal that gets its energy by eating other animals"},{"n":"9","text":"Describe a decomposer as an organism that gets its energy from dead or waste organic material"},{"n":"10","text":"Use food chains and food webs to describe the impact humans have through overharvesting of food species and through introducing foreign species to a habitat"},{"n":"11","text":"Draw, describe and interpret pyramids of numbers and pyramids of biomass"},{"n":"12","text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"},{"n":"13","text":"Describe a trophic level as the position of an organism in a food chain, food web or ecological pyramid"},{"n":"14","text":"Identify the following as the trophic levels in food webs, food chains and ecological pyramids: producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers"}],"supplement":[{"n":"15","text":"Draw, describe and interpret pyramids of energy"},{"n":"16","text":"Discuss the advantages of using a pyramid of energy rather than pyramids of numbers or biomass to represent a food chain"},{"n":"17","text":"Explain why the transfer of energy from one trophic level to another is often not efficient"},{"n":"18","text":"Explain, in terms of energy loss, why food chains usually have fewer than five trophic levels"},{"n":"19","text":"Explain why it is more energy efficient for humans to eat crop plants than to eat livestock that have been fed on crop plants"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"n":"1","text":"Describe the carbon cycle, limited to: photosynthesis, respiration, feeding, decomposition, formation of fossil fuels and combustion"}],"supplement":[{"n":"2","text":"Describe the nitrogen cycle with reference to: • decomposition of plant and animal protein to ammonium ions • nitrification • nitrogen fixation by lightning and bacteria • absorption of nitrate ions by plants • production of amino acids and proteins • feeding and digestion of proteins • deamination • denitrification"},{"n":"3","text":"State the roles of microorganisms in the nitrogen cycle, limited to: decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Populations","core":[{"n":"1","text":"Describe a population as a group of organisms of one species, living in the same area, at the same time"},{"n":"2","text":"Describe a community as all of the populations of different species in an ecosystem"},{"n":"3","text":"Describe an ecosystem as a unit containing the community of organisms and their environment, interacting together"},{"n":"4","text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, competition, predation and disease"},{"n":"5","text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid curve of population growth for a population growing in an environment with limited resources"},{"n":"6","text":"Interpret graphs and diagrams of population growth"}],"supplement":[{"n":"7","text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Human influences on ecosystems","sections":[{"n":"20.1","title":"Food supply","core":[{"n":"1","text":"Describe how humans have increased food production, limited to:\n(a) \u0007agricultural machinery to use larger areas of land and improve efficiency\n(b) chemical fertilisers to improve yields\n(c) insecticides to improve quality and yield\n(d) \u0007herbicides to reduce competition with weeds\n(e) \u0007selective breeding to improve production by crop plants and livestock"},{"n":"2","text":"Describe the advantages and disadvantages of large-scale monocultures of crop plants"},{"n":"3","text":"Describe the advantages and disadvantages of intensive livestock production"}],"supplement":[]},{"n":"20.2","title":"Habitat destruction","core":[{"n":"1","text":"Describe biodiversity as the number of different species that live in an area"},{"n":"2","text":"Describe the reasons for habitat destruction, including:\n(a) \u0007increased area for housing, crop plant production and livestock production\n(b) extraction of natural resources\n(c) freshwater and marine pollution"},{"n":"3","text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"n":"4","text":"Explain the undesirable effects of deforestation as an example of habitat destruction, to include: reducing biodiversity, extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[]},{"n":"20.3","title":"Pollution","core":[{"n":"1","text":"Describe the effects of untreated sewage and excess fertiliser on aquatic ecosystems"},{"n":"2","text":"Describe the effects of non-biodegradable plastics, in both aquatic and terrestrial ecosystems"},{"n":"3","text":"Describe the sources and effects of pollution of the air by methane and carbon dioxide, limited to: the enhanced greenhouse effect and climate change"}],"supplement":[{"n":"4","text":"Explain the process of eutrophication of water, limited to: • increased availability of nitrate and other ions • increased growth of producers • increased decomposition after death of producers • increased aerobic respiration by decomposers • reduction in dissolved oxygen • death of organisms requiring dissolved oxygen in water"}]},{"n":"20.4","title":"Conservation","core":[{"n":"1","text":"Describe a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"n":"2","text":"State that some resources can be conserved and managed sustainably, limited to forests and fish stocks"},{"n":"3","text":"Explain why organisms become endangered or extinct, including: climate change, habitat destruction, hunting, overharvesting, pollution and introduced species"},{"n":"4","text":"Describe how endangered species can be conserved, limited to:\n(a) \u0007monitoring and protecting species and habitats\n(b) education\n(c) captive breeding programmes\n(d) seed banks"}],"supplement":[{"n":"5","text":"Explain how forests can be conserved using: education, protected areas, quotas and replanting"},{"n":"6","text":"Explain how fish stocks can be conserved using: education, closed seasons, protected areas, controlled net types and mesh size, quotas and monitoring"},{"n":"7","text":"Describe the reasons for conservation programmes, limited to:\n(a) maintaining or increasing biodiversity\n(b) reducing extinction\n(c) protecting vulnerable ecosystems\n(d) \u0007maintaining ecosystem functions, limited to nutrient cycling and resource provision, including food, drugs, fuel and genes"},{"n":"8","text":"Describe the use of artificial insemination (AI) and in vitro fertilisation (IVF) in captive breeding programmes"},{"n":"9","text":"Explain the risks to a species if its population size decreases, reducing genetic variation (knowledge of genetic drift is not required)"}]}]},{"n":"21","title":"Biotechnology and genetic modification","sections":[{"n":"21.1","title":"Biotechnology and genetic modification","core":[{"n":"1","text":"State that bacteria are useful in biotechnology and genetic modification due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"n":"2","text":"Discuss why bacteria are useful in biotechnology and genetic modification, limited to:\n(a) \u0007few ethical concerns over their manipulation and growth\n(b) \u0007the presence of plasmids"}]},{"n":"21.2","title":"Biotechnology","core":[{"n":"1","text":"Describe the role of anaerobic respiration in yeast during the production of ethanol for biofuels"},{"n":"2","text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"n":"3","text":"Describe the use of pectinase in fruit juice production"},{"n":"4","text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"n":"5","text":"Explain the use of lactase to produce lactose- free milk"},{"n":"6","text":"Describe how fermenters can be used for the large-scale production of useful products by bacteria and fungi, including insulin, penicillin and mycoprotein"},{"n":"7","text":"Describe and explain the conditions that need to be controlled in a fermenter, including: temperature, pH, oxygen, nutrient supply and waste products"}]},{"n":"21.3","title":"Genetic modification","core":[{"n":"1","text":"Describe genetic modification as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"n":"2","text":"Outline examples of genetic modification:\n(a) \u0007the insertion of human genes into bacteria to produce human proteins\n(b) \u0007the insertion of genes into crop plants to confer resistance to herbicides\n(c) \u0007the insertion of genes into crop plants to confer resistance to insect pests\n(d) \u0007the insertion of genes into crop plants to improve nutritional qualities"}],"supplement":[{"n":"3","text":"Outline the process of genetic modification using bacterial production of a human protein as an example, limited to:\n(a) \u0007isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n(b) \u0007cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n(c) \u0007insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n(d) \u0007insertion of recombinant plasmids into bacteria (specific details are not required)\n(e) \u0007multiplication of bacteria containing recombinant plasmids\n(f) \u0007expression in bacteria of the human gene to make the human protein"},{"n":"4","text":"Discuss the advantages and disadvantages of genetically modifying crops, including soya, maize and rice"}]}]}]},{"id":"2023-2025","label":"2023–2025","topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"n":"1","text":"Describe the characteristics of living organisms by describing:\n(a) \u0007movement as an action by an organism or part of an organism causing a change of position or place\n(b) \u0007respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n(c) \u0007sensitivity as the ability to detect and respond to changes in the internal or external environment\n(d) \u0007growth as a permanent increase in size and dry mass\n(e) \u0007reproduction as the processes that make more of the same kind of organism\n(f) \u0007excretion as the removal of the waste products of metabolism and substances in excess of requirements\n(g) \u0007nutrition as the taking in of materials for energy, growth and development"}],"supplement":[]},{"n":"1.2","title":"Concept and uses of classification systems","core":[{"n":"1","text":"State that organisms can be classified into groups by the features that they share"},{"n":"2","text":"Describe a species as a group of organisms that can reproduce to produce fertile offspring"},{"n":"3","text":"Describe the binomial system of naming species as an internationally agreed system in which the scientiﬁc name of an organism is made up of two parts showing the genus and species"},{"n":"4","text":"Construct and use dichotomous keys based on identifiable features"}],"supplement":[{"n":"5","text":"Explain that classiﬁcation systems aim to reﬂect evolutionary relationships"},{"n":"6","text":"Explain that the sequences of bases in DNA are used as a means of classiﬁcation"},{"n":"7","text":"Explain that groups of organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"n":"1","text":"\u0007State the main features used to place animals and plants into the appropriate kingdoms"},{"n":"2","text":"\u0007State the main features used to place organisms into groups within the animal kingdom, limited to:\n(a) \u0007the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish\n(b) \u0007the main groups of arthropods: myriapods, insects, arachnids, crustaceans"},{"n":"3","text":"\u0007Classify organisms using the features identified in 1.3.1 and 1.3.2"}],"supplement":[{"n":"4","text":"\u0007State the main features used to place all organisms into one of the five kingdoms: animal, plant, fungus, prokaryote, protoctist"},{"n":"5","text":"\u0007State the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"n":"6","text":"\u0007Classify organisms using the features identified in 1.3.4 and 1.3.5"},{"n":"7","text":"\u0007State the features of viruses, limited to a protein coat and genetic material"}]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure","core":[{"n":"1","text":"\u0007Describe and compare the structure of a plant cell with an animal cell, limited to: cell wall, cell membrane, nucleus, cytoplasm, chloroplasts, ribosomes, mitochondria, vacuoles"},{"n":"2","text":"\u0007Describe the structure of a bacterial cell, limited to: cell wall, cell membrane, cytoplasm, ribosomes, circular DNA, plasmids"},{"n":"3","text":"\u0007Identify the cell structures listed in 2.1.1 and 2.1.2 in diagrams and images of plant, animal and bacterial cells"},{"n":"4","text":"\u0007Describe the functions of the structures listed in 2.1.1 and 2.1.2 in plant, animal and bacterial cells"},{"n":"5","text":"\u0007State that new cells are produced by division of existing cells"},{"n":"6","text":"\u0007State that specialised cells have specific functions, limited to:\n(a) \u0007ciliated cells – movement of mucus in the trachea and bronchi\n(b) root hair cells – absorption\n(c) palisade mesophyll cells – photosynthesis\n(d) neurones – conduction of electrical impulses\n(e) red blood cells – transport of oxygen\n(f) sperm and egg cells (gametes) – reproduction"},{"n":"7","text":"\u0007Describe the meaning of the terms: cell, tissue, organ, organ system and organism as illustrated by examples given in the syllabus"}],"supplement":[]},{"n":"2.2","title":"Size of specimens","core":[{"n":"1","text":"State and use the formula: magnification = image size ÷ actual size"},{"n":"2","text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"n":"3","text":"Convert measurements between millimetres (mm) and micrometres (μm)"}]}]},{"n":"3","title":"Movement into and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"n":"1","text":"Describe diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration (i.e. down a concentration gradient), as a result of their random movement"},{"n":"2","text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"n":"3","text":"State that some substances move into and out of cells by diffusion through the cell membrane"},{"n":"4","text":"Describe the importance of diffusion of gases and solutes in living organisms"},{"n":"5","text":"Investigate the factors that influence diffusion, limited to: surface area, temperature, concentration gradient and distance"}],"supplement":[]},{"n":"3.2","title":"Osmosis","core":[{"n":"1","text":"Describe the role of water as a solvent in organisms with reference to digestion, excretion and transport"},{"n":"2","text":"State that water diffuses through partially permeable membranes by osmosis"},{"n":"3","text":"State that water moves into and out of cells by osmosis through the cell membrane"},{"n":"4","text":"Investigate osmosis using materials such as dialysis tubing"},{"n":"5","text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"n":"6","text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"n":"7","text":"Describe osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"n":"8","text":"Explain the effects on plant cells of immersing them in solutions of different concentrations by using the terms: turgid, turgor pressure, plasmolysis, flaccid"},{"n":"9","text":"Explain the importance of water potential and osmosis in the uptake and loss of water by organisms"}]},{"n":"3.3","title":"Active transport","core":[{"n":"1","text":"Describe active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration (i.e. against a concentration gradient), using energy from respiration"}],"supplement":[{"n":"2","text":"Explain the importance of active transport as a process for movement of molecules or ions across membranes, including ion uptake by root hairs"},{"n":"3","text":"State that protein carriers move molecules or ions across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4.1","title":"Biological molecules","core":[{"n":"1","text":"List the chemical elements that make up: carbohydrates, fats and proteins"},{"n":"2","text":"State that large molecules are made from smaller molecules, limited to:\n(a) starch, glycogen and cellulose from glucose\n(b) proteins from amino acids\n(c) fats and oils from fatty acids and glycerol"},{"n":"3","text":"Describe the use of:\n(a) iodine solution test for starch\n(b) Benedict’s solution test for reducing sugars\n(c) biuret test for proteins\n(d) ethanol emulsion test for fats and oils\n(e) DCPIP test for vitamin C"}],"supplement":[{"n":"4","text":"Describe the structure of a DNA molecule:\n(a) \u0007two strands coiled together to form a double helix\n(b) each strand contains chemicals called bases\n(c) \u0007bonds between pairs of bases hold the strands together\n(d) \u0007the bases always pair up in the same way: A with T, and C with G (full names are not required)"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5.1","title":"Enzymes","core":[{"n":"1","text":"Describe a catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"n":"2","text":"Describe enzymes as proteins that are involved in all metabolic reactions, where they function as biological catalysts"},{"n":"3","text":"Describe why enzymes are important in all living organisms in terms of a reaction rate necessary to sustain life"},{"n":"4","text":"Describe enzyme action with reference to the shape of the active site of an enzyme being complementary to its substrate and the formation of products"},{"n":"5","text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity with reference to optimum temperature and denaturation"}],"supplement":[{"n":"6","text":"Explain enzyme action with reference to: active site, enzyme-substrate complex, substrate and product"},{"n":"7","text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"n":"8","text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"n":"9","text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"n":"1","text":"Describe photosynthesis as the process by which plants synthesise carbohydrates from raw materials using energy from light"},{"n":"2","text":"State the word equation for photosynthesis as: carbon dioxide + water → glucose + oxygen in the presence of light and chlorophyll"},{"n":"3","text":"State that chlorophyll is a green pigment that is found in chloroplasts"},{"n":"4","text":"State that chlorophyll transfers energy from light into energy in chemicals, for the synthesis of carbohydrates"},{"n":"5","text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis, limited to:\n(a) starch as an energy store\n(b) cellulose to build cell walls\n(c) glucose used in respiration to provide energy\n(d) sucrose for transport in the phloem\n(e) nectar to attract insects for pollination"},{"n":"6","text":"Explain the importance of:\n(a) nitrate ions for making amino acids\n(b) magnesium ions for making chlorophyll"},{"n":"7","text":"Investigate the need for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"n":"8","text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis"},{"n":"9","text":"Investigate and describe the effect of light and dark conditions on gas exchange in an aquatic plant using hydrogencarbonate indicator solution"}],"supplement":[{"n":"10","text":"State the balanced chemical equation for photosynthesis as: 6CO2 + 6H2O → C6H12O6 + 6O2"},{"n":"11","text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"}]},{"n":"6.2","title":"Leaf structure","core":[{"n":"1","text":"State that most leaves have a large surface area and are thin, and explain how these features are adaptations for photosynthesis"},{"n":"2","text":"Identify in diagrams and images the following structures in the leaf of a dicotyledonous plant: chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, air spaces, vascular bundles, xylem and phloem"},{"n":"3","text":"Explain how the structures listed in 6.2.2 adapt leaves for photosynthesis"}],"supplement":[]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"n":"1","text":"Describe what is meant by a balanced diet"},{"n":"2","text":"State the principal dietary sources and describe the importance of:\n(a) carbohydrates\n(b) fats and oils\n(c) proteins\n(d) vitamins, limited to C and D\n(e) mineral ions, limited to calcium and iron\n(f) fibre (roughage)\n(g) water"},{"n":"3","text":"State the causes of scurvy and rickets"}],"supplement":[]},{"n":"7.2","title":"Digestive system","core":[{"n":"1","text":"Identify in diagrams and images the main organs of the digestive system, limited to:\n(a) \u0007alimentary canal: mouth, oesophagus, stomach, small intestine (duodenum and ileum) and large intestine (colon, rectum, anus)\n(b) \u0007associated organs: salivary glands, pancreas, liver and gall bladder"},{"n":"2","text":"Describe the functions of the organs of the digestive system listed in 7.2.1, in relation to:\n(a) \u0007ingestion – the taking of substances, e.g. food and drink, into the body\n(b) digestion – the breakdown of food\n(c) \u0007absorption – the movement of nutrients from the intestines into the blood\n(d) \u0007assimilation – uptake and use of nutrients by cells\n(e) \u0007egestion – the removal of undigested food from the body as faeces"}],"supplement":[]},{"n":"7.3","title":"Physical digestion","core":[{"n":"1","text":"Describe physical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"n":"2","text":"State that physical digestion increases the surface area of food for the action of enzymes in chemical digestion"},{"n":"3","text":"Identify in diagrams and images the types of human teeth: incisors, canines, premolars and molars"},{"n":"4","text":"Describe the structure of human teeth, limited to: enamel, dentine, pulp, nerves, blood vessels and cement, and understand that teeth are embedded in bone and the gums"},{"n":"5","text":"Describe the functions of the types of human teeth in physical digestion of food"},{"n":"6","text":"Describe the function of the stomach in physical digestion"}],"supplement":[{"n":"7","text":"Outline the role of bile in emulsifying fats and oils to increase the surface area for chemical digestion"}]},{"n":"7.4","title":"Chemical digestion","core":[{"n":"1","text":"Describe chemical digestion as the break down of large insoluble molecules into small soluble molecules"},{"n":"2","text":"State the role of chemical digestion in producing small soluble molecules that can be absorbed"},{"n":"3","text":"Describe the functions of enzymes as follows:\n(a) \u0007amylase breaks down starch to simple reducing sugars\n(b) proteases break down protein to amino acids\n(c) \u0007lipase breaks down fats and oils to fatty acids and glycerol"},{"n":"4","text":"State where, in the digestive system, amylase, protease and lipase are secreted and where they act"},{"n":"5","text":"Describe the functions of hydrochloric acid in gastric juice, limited to killing harmful microorganisms in food and providing an acidic pH for optimum enzyme activity"}],"supplement":[{"n":"6","text":"Describe the digestion of starch in the digestive system:\n(a) amylase breaks down starch to maltose\n(b) \u0007maltase breaks down maltose to glucose on the membranes of the epithelium lining the small intestine"},{"n":"7","text":"Describe the digestion of protein by proteases in the digestive system:\n(a) \u0007pepsin breaks down protein in the acidic conditions of the stomach\n(b) \u0007trypsin breaks down protein in the alkaline conditions of the small intestine"},{"n":"8","text":"Explain that bile is an alkaline mixture that neutralises the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"}]},{"n":"7.5","title":"Absorption","core":[{"n":"1","text":"State that the small intestine is the region where nutrients are absorbed"},{"n":"2","text":"State that most water is absorbed from the small intestine but that some is also absorbed from the colon"}],"supplement":[{"n":"3","text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"n":"4","text":"Describe the structure of a villus"},{"n":"5","text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Xylem and phloem","core":[{"n":"1","text":"State the functions of xylem and phloem:\n(a) \u0007xylem – transport of water and mineral ions, and support\n(b) \u0007phloem – transport of sucrose and amino acids"},{"n":"2","text":"Identify in diagrams and images the position of xylem and phloem as seen in sections of roots, stems and leaves of non-woody dicotyledonous plants"}],"supplement":[{"n":"3","text":"Relate the structure of xylem vessels to their function, limited to:\n(a) \u0007thick walls with lignin (details of lignification are not required)\n(b) no cell contents\n(c) \u0007cells joined end to end with no cross walls to form a long continuous tube"}]},{"n":"8.2","title":"Water uptake","core":[{"n":"1","text":"Identify in diagrams and images root hair cells and state their functions"},{"n":"2","text":"State that the large surface area of root hairs increases the uptake of water and mineral ions"},{"n":"3","text":"Outline the pathway taken by water through the root, stem and leaf as: root hair cells, root cortex cells, xylem, mesophyll cells"},{"n":"4","text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[]},{"n":"8.3","title":"Transpiration","core":[{"n":"1","text":"Describe transpiration as the loss of water vapour from leaves"},{"n":"2","text":"State that water evaporates from the surfaces of the mesophyll cells into the air spaces and then diffuses out of the leaves through the stomata as water vapour"},{"n":"3","text":"Investigate and describe the effects of variation of temperature and wind speed on transpiration rate"}],"supplement":[{"n":"4","text":"Explain how water vapour loss is related to: the large internal surface area provided by the interconnecting air spaces between mesophyll cells and the size and number of stomata"},{"n":"5","text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by forces of attraction between water molecules"},{"n":"6","text":"Explain the effects on the rate of transpiration of varying the following factors: temperature, wind speed and humidity"},{"n":"7","text":"Explain how and why wilting occurs"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"n":"1","text":"Describe translocation as the movement of sucrose and amino acids in phloem from sources to sinks"},{"n":"2","text":"Describe:\n(a) \u0007sources as the parts of plants that release sucrose or amino acids\n(b) \u0007sinks as the parts of plants that use or store sucrose or amino acids"},{"n":"3","text":"Explain why some parts of a plant may act as a source and a sink at different times"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Circulatory systems","core":[{"n":"1","text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"n":"2","text":"Describe the single circulation of a fish"},{"n":"3","text":"Describe the double circulation of a mammal"},{"n":"4","text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"n":"1","text":"Identify in diagrams and images the structures of the mammalian heart, limited to: muscular wall, septum, left and right ventricles, left and right atria, one-way valves and coronary arteries"},{"n":"2","text":"State that blood is pumped away from the heart in arteries and returns to the heart in veins"},{"n":"3","text":"State that the activity of the heart may be monitored by: ECG, pulse rate and listening to sounds of valves closing"},{"n":"4","text":"Investigate and describe the effect of physical activity on the heart rate"},{"n":"5","text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors including: diet, lack of exercise, stress, smoking, genetic predisposition, age and sex"},{"n":"6","text":"Discuss the roles of diet and exercise in reducing the risk of coronary heart disease"}],"supplement":[{"n":"7","text":"Identify in diagrams and images the atrioventricular and semilunar valves in the mammalian heart"},{"n":"8","text":"Explain the relative thickness of:\n(a) \u0007the muscle walls of the left and right ventricles\n(b) \u0007the muscle walls of the atria compared to those of the ventricles"},{"n":"9","text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"n":"10","text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"n":"11","text":"Explain the effect of physical activity on the heart rate"}]},{"n":"9.3","title":"Blood vessels","core":[{"n":"1","text":"Describe the structure of arteries, veins and capillaries, limited to: relative thickness of wall, diameter of the lumen and the presence of valves in veins"},{"n":"2","text":"State the functions of capillaries"},{"n":"3","text":"Identify in diagrams and images the main blood vessels to and from the:\n(a) \u0007heart, limited to: vena cava, aorta, pulmonary artery and pulmonary vein\n(b) \u0007lungs, limited to: pulmonary artery and pulmonary vein\n(c) kidney, limited to: renal artery and renal vein"}],"supplement":[{"n":"4","text":"Explain how the structure of arteries and veins is related to the pressure of the blood that they transport"},{"n":"5","text":"Explain how the structure of capillaries is related to their functions"},{"n":"6","text":"Identify, in diagrams and images, the main blood vessels to and from the liver as: hepatic artery, hepatic veins and hepatic portal vein"}]},{"n":"9.4","title":"Blood","core":[{"n":"1","text":"List the components of blood as: red blood cells, white blood cells, platelets and plasma"},{"n":"2","text":"Identify red and white blood cells in photomicrographs and diagrams"},{"n":"3","text":"State the functions of the following components of blood:\n(a) \u0007red blood cells in transporting oxygen, including the role of haemoglobin\n(b) \u0007white blood cells in phagocytosis and antibody production\n(c) platelets in clotting (details are not required)\n(d) \u0007plasma in the transport of blood cells, ions, nutrients, urea, hormones and carbon dioxide"},{"n":"4","text":"State the roles of blood clotting as preventing blood loss and the entry of pathogens"}],"supplement":[{"n":"5","text":"Identify lymphocytes and phagocytes in photomicrographs and diagrams"},{"n":"6","text":"State the functions of:\n(a) lymphocytes – antibody production\n(b) \u0007phagocytes – engulfing pathogens by phagocytosis"},{"n":"7","text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10.1","title":"Diseases and immunity","core":[{"n":"1","text":"Describe a pathogen as a disease-causing organism"},{"n":"2","text":"Describe a transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"n":"3","text":"State that a pathogen is transmitted:\n(a) \u0007by direct contact, including through blood and other body fluids\n(b) \u0007indirectly, including from contaminated surfaces, food, animals and air"},{"n":"4","text":"Describe the body defences, limited to: skin, hairs in the nose, mucus, stomach acid and white blood cells"},{"n":"5","text":"Explain the importance of the following in controlling the spread of disease:\n(a) a clean water supply\n(b) hygienic food preparation\n(c) good personal hygiene\n(d) waste disposal\n(e) \u0007sewage treatment (details of the stages of sewage treatment are not required)"}],"supplement":[{"n":"6","text":"Describe active immunity as defence against a pathogen by antibody production in the body"},{"n":"7","text":"State that each pathogen has its own antigens, which have specific shapes"},{"n":"8","text":"Describe antibodies as proteins that bind to antigens leading to direct destruction of pathogens or marking of pathogens for destruction by phagocytes"},{"n":"9","text":"State that specific antibodies have complementary shapes which fit specific antigens"},{"n":"10","text":"Explain that active immunity is gained after an infection by a pathogen or by vaccination"},{"n":"11","text":"Outline the process of vaccination:\n(a) \u0007weakened pathogens or their antigens are put into the body\n(b) \u0007the antigens stimulate an immune response by lymphocytes which produce antibodies\n(c) \u0007memory cells are produced that give long-term immunity"},{"n":"12","text":"Explain the role of vaccination in controlling the spread of diseases"},{"n":"13","text":"Explain that passive immunity is a short-term defence against a pathogen by antibodies acquired from another individual, including across the placenta and in breast milk"},{"n":"14","text":"Explain the importance of breast-feeding for the development of passive immunity in infants"},{"n":"15","text":"State that memory cells are not produced in passive immunity"},{"n":"16","text":"Describe cholera as a disease caused by a bacterium which is transmitted in contaminated water"},{"n":"17","text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of ions from the blood"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11.1","title":"Gas exchange in humans","core":[{"n":"1","text":"Describe the features of gas exchange surfaces in humans, limited to: large surface area, thin surface, good blood supply and good ventilation with air"},{"n":"2","text":"Identify in diagrams and images the following parts of the breathing system: lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"n":"3","text":"Investigate the differences in composition between inspired and expired air using limewater as a test for carbon dioxide"},{"n":"4","text":"Describe the differences in composition between inspired and expired air, limited to: oxygen, carbon dioxide and water vapour"},{"n":"5","text":"Investigate and describe the effects of physical activity on the rate and depth of breathing"}],"supplement":[{"n":"6","text":"Identify in diagrams and images the internal and external intercostal muscles"},{"n":"7","text":"State the function of cartilage in the trachea"},{"n":"8","text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"n":"9","text":"Explain the differences in composition between inspired and expired air"},{"n":"10","text":"Explain the link between physical activity and the rate and depth of breathing in terms of: an increased carbon dioxide concentration in the blood, which is detected by the brain, leading to an increased rate and greater depth of breathing"},{"n":"11","text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the breathing system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"n":"1","text":"State the uses of energy in living organisms, including: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"n":"2","text":"Investigate and describe the effect of temperature on respiration in yeast"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"n":"1","text":"Describe aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"n":"2","text":"State the word equation for aerobic respiration as: glucose + oxygen → carbon dioxide + water"}],"supplement":[{"n":"3","text":"State the balanced chemical equation for aerobic respiration as: C6H12O6 + 6O2 → 6CO2 + 6H2O"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"n":"1","text":"Describe anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"n":"2","text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"},{"n":"3","text":"State the word equation for anaerobic respiration in yeast as: glucose → alcohol + carbon dioxide"},{"n":"4","text":"State the word equation for anaerobic respiration in muscles during vigorous exercise as: glucose → lactic acid"}],"supplement":[{"n":"5","text":"State the balanced chemical equation for anaerobic respiration in yeast as: C6H12O6 → 2C2H5OH + 2CO2"},{"n":"6","text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"n":"7","text":"Outline how the oxygen debt is removed after exercise, limited to:\n(a) \u0007continuation of fast heart rate to transport lactic acid in the blood from the muscles to the liver\n(b) \u0007continuation of deeper and faster breathing to supply oxygen for aerobic respiration of lactic acid\n(c) aerobic respiration of lactic acid in the liver"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13.1","title":"Excretion in humans","core":[{"n":"1","text":"State that carbon dioxide is excreted through the lungs"},{"n":"2","text":"State that the kidneys excrete urea and excess water and ions"},{"n":"3","text":"Identify in diagrams and images the kidneys, ureters, bladder and urethra"}],"supplement":[{"n":"4","text":"Identify in diagrams and images the structure of the kidney, limited to the cortex and medulla"},{"n":"5","text":"Outline the structure and function of a nephron and its associated blood vessels, limited to:\n(a) \u0007the role of the glomerulus in the filtration from the blood of water, glucose, urea and ions\n(b) \u0007the role of the nephron in the reabsorption of all of the glucose, some of the ions and most of the water back into the blood\n(c) \u0007the formation of urine containing urea, excess water and excess ions (details of these processes are not required)"},{"n":"6","text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins"},{"n":"7","text":"State that urea is formed in the liver from excess amino acids"},{"n":"8","text":"Describe deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"n":"9","text":"Explain the importance of excretion, limited to toxicity of urea"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Coordination and response","core":[{"n":"1","text":"State that electrical impulses travel along neurones"},{"n":"2","text":"Describe the mammalian nervous system in terms of:\n(a) \u0007the central nervous system (CNS) consisting of the brain and the spinal cord\n(b) \u0007the peripheral nervous system (PNS) consisting of the nerves outside of the brain and spinal cord"},{"n":"3","text":"Describe the role of the nervous system as coordination and regulation of body functions"},{"n":"4","text":"Identify in diagrams and images sensory, relay and motor neurones"},{"n":"5","text":"Describe a simple reflex arc in terms of: receptor, sensory neurone, relay neurone, motor neurone and effector"},{"n":"6","text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"n":"7","text":"Describe a synapse as a junction between two neurones"}],"supplement":[{"n":"8","text":"Describe the structure of a synapse, including the presence of vesicles containing neurotransmitter molecules, the synaptic gap and receptor proteins"},{"n":"9","text":"Describe the events at a synapse as:\n(a) \u0007an impulse stimulates the release of neurotransmitter molecules from vesicles into the synaptic gap\n(b) \u0007the neurotransmitter molecules diffuse across the gap\n(c) \u0007neurotransmitter molecules bind with receptor proteins on the next neurone\n(d) \u0007an impulse is then stimulated in the next neurone"},{"n":"10","text":"State that synapses ensure that impulses travel in one direction only"}]},{"n":"14.2","title":"Sense organs","core":[{"n":"1","text":"Describe sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"n":"2","text":"Identify in diagrams and images the structures of the eye, limited to: cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"n":"3","text":"Describe the function of each part of the eye, limited to:\n(a) cornea – refracts light\n(b) \u0007iris – controls how much light enters the pupil\n(c) lens – focuses light on to the retina\n(d) \u0007retina – contains light receptors, some sensitive to light of different colours\n(e) optic nerve – carries impulses to the brain"},{"n":"4","text":"Explain the pupil reflex, limited to changes in light intensity and pupil diameter"}],"supplement":[{"n":"5","text":"Explain the pupil reflex in terms of the antagonistic action of circular and radial muscles in the iris"},{"n":"6","text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"n":"7","text":"Describe the distribution of rods and cones in the retina of a human"},{"n":"8","text":"Outline the function of rods and cones, limited to:\n(a) greater sensitivity of rods for night vision\n(b) \u0007three different kinds of cones, absorbing light of different colours, for colour vision"},{"n":"9","text":"Identify in diagrams and images the position of the fovea and state its function"}]},{"n":"14.3","title":"Hormones","core":[{"n":"1","text":"Describe a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"n":"2","text":"Identify in diagrams and images specific endocrine glands and state the hormones they secrete, limited to:\n(a) adrenal glands and adrenaline\n(b) pancreas and insulin\n(c) testes and testosterone\n(d) ovaries and oestrogen"},{"n":"3","text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to:\n(a) increased breathing rate\n(b) increased heart rate\n(c) increased pupil diameter"},{"n":"4","text":"Compare nervous and hormonal control, limited to speed of action and duration of effect"}],"supplement":[{"n":"5","text":"State that glucagon is secreted by the pancreas"},{"n":"6","text":"Describe the role of adrenaline in the control of metabolic activity, limited to:\n(a) \u0007increasing the blood glucose concentration\n(b) increasing heart rate"}]},{"n":"14.4","title":"Homeostasis","core":[{"n":"1","text":"Describe homeostasis as the maintenance of a constant internal environment"},{"n":"2","text":"State that insulin decreases blood glucose concentration"}],"supplement":[{"n":"3","text":"Explain the concept of homeostatic control by negative feedback with reference to a set point"},{"n":"4","text":"Describe the control of blood glucose concentration by the liver and the roles of insulin and glucagon"},{"n":"5","text":"Outline the treatment of Type 1 diabetes"},{"n":"6","text":"Identify in diagrams and images of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"n":"7","text":"Describe the maintenance of a constant internal body temperature in mammals in terms of: insulation, sweating, shivering and the role of the brain"},{"n":"8","text":"Describe the maintenance of a constant internal body temperature in mammals in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"n":"1","text":"Describe gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"n":"2","text":"Describe phototropism as a response in which parts of a plant grow towards or away from the direction of the light source"},{"n":"3","text":"Investigate and describe gravitropism and phototropism in shoots and roots"}],"supplement":[{"n":"4","text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"n":"5","text":"Explain the role of auxin in controlling shoot growth, limited to:\n(a) auxin is made in the shoot tip\n(b) \u0007auxin diffuses through the plant from the shoot tip\n(c) \u0007auxin is unequally distributed in response to light and gravity\n(d) auxin stimulates cell elongation"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"n":"1","text":"Describe a drug as any substance taken into the body that modifies or affects chemical reactions in the body"},{"n":"2","text":"Describe the use of antibiotics for the treatment of bacterial infections"},{"n":"3","text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"n":"4","text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"n":"5","text":"Explain how using antibiotics only when essential can limit the development of resistant bacteria such as MRSA"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"n":"1","text":"Describe asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"n":"2","text":"Identify examples of asexual reproduction in diagrams, images and information provided"}],"supplement":[{"n":"3","text":"Discuss the advantages and disadvantages of asexual reproduction:\n(a) to a population of a species in the wild\n(b) to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"n":"1","text":"Describe sexual reproduction as a process involving the fusion of the nuclei of two gametes to form a zygote and the production of offspring that are genetically different from each other"},{"n":"2","text":"Describe fertilisation as the fusion of the nuclei of gametes"}],"supplement":[{"n":"3","text":"State that nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"n":"4","text":"Discuss the advantages and disadvantages of sexual reproduction:\n(a) to a population of a species in the wild\n(b) to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"n":"1","text":"Identify in diagrams and images and draw the following parts of an insect-pollinated flower: sepals, petals, stamens, filaments, anthers, carpels, style, stigma, ovary and ovules"},{"n":"2","text":"State the functions of the structures listed in 16.3.1"},{"n":"3","text":"Identify in diagrams and images and describe the anthers and stigmas of a wind-pollinated flower"},{"n":"4","text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"n":"5","text":"Describe pollination as the transfer of pollen grains from an anther to a stigma"},{"n":"6","text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"n":"7","text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"n":"8","text":"Investigate and describe the environmental conditions that affect germination of seeds, limited to the requirement for: water, oxygen and a suitable temperature"}],"supplement":[{"n":"9","text":"Describe self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or a different flower on the same plant"},{"n":"10","text":"Describe cross-pollination as the transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"n":"11","text":"Discuss the potential effects of self-pollination and cross-pollination on a population, in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"n":"12","text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"n":"1","text":"Identify on diagrams and state the functions of the following parts of the male reproductive system: testes, scrotum, sperm ducts, prostate gland, urethra and penis"},{"n":"2","text":"Identify on diagrams and state the functions of the following parts of the female reproductive system: ovaries, oviducts, uterus, cervix and vagina"},{"n":"3","text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell)"},{"n":"4","text":"Explain the adaptive features of sperm, limited to: flagellum, mitochondria and enzymes in the acrosome"},{"n":"5","text":"Explain the adaptive features of egg cells, limited to: energy stores and the jelly coat that changes at fertilisation"},{"n":"6","text":"Compare male and female gametes in terms of: size, structure, motility and numbers"},{"n":"7","text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the lining of the uterus"},{"n":"8","text":"Identify on diagrams and state the functions of the following in the development of the fetus: umbilical cord, placenta, amniotic sac and amniotic fluid"}],"supplement":[{"n":"9","text":"Describe the function of the placenta and umbilical cord in relation to the exchange of dissolved nutrients, gases and excretory products between the blood of the mother and the blood of the fetus"},{"n":"10","text":"State that some pathogens and toxins can pass across the placenta and affect the fetus"}]},{"n":"16.5","title":"Sexual hormones in humans","core":[{"n":"1","text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"n":"2","text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"n":"3","text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"n":"4","text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Sexually transmitted infections","core":[{"n":"1","text":"Describe a sexually transmitted infection (STI) as an infection that is transmitted through sexual contact"},{"n":"2","text":"State that human immunodeficiency virus (HIV) is a pathogen that causes an STI"},{"n":"3","text":"State that HIV infection may lead to AIDS"},{"n":"4","text":"Describe the methods of transmission of HIV"},{"n":"5","text":"Explain how the spread of STIs is controlled"}],"supplement":[]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Chromosomes, genes and proteins","core":[{"n":"1","text":"State that chromosomes are made of DNA, which contains genetic information in the form of genes"},{"n":"2","text":"Define a gene as a length of DNA that codes for a protein"},{"n":"3","text":"Define an allele as an alternative form of a gene"},{"n":"4","text":"Describe the inheritance of sex in humans with reference to X and Y chromosomes"}],"supplement":[{"n":"5","text":"State that the sequence of bases in a gene determines the sequence of amino acids used to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"n":"6","text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"n":"7","text":"Explain that DNA controls cell function by controlling the production of proteins, including enzymes, membrane carriers and receptors for neurotransmitters"},{"n":"8","text":"Explain how a protein is made, limited to: • the gene coding for the protein remains in the nucleus • messenger RNA (mRNA) is a copy of a gene • mRNA molecules are made in the nucleus and move to the cytoplasm • the mRNA passes through ribosomes • the ribosome assembles amino acids into protein molecules • the specific sequence of amino acids is determined by the sequence of bases in the mRNA \u0007(knowledge of the details of transcription or translation is not required)"},{"n":"9","text":"Explain that most body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs"},{"n":"10","text":"Describe a haploid nucleus as a nucleus containing a single set of chromosomes"},{"n":"11","text":"Describe a diploid nucleus as a nucleus containing two sets of chromosomes"},{"n":"12","text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.2","title":"Mitosis","core":[],"supplement":[{"n":"1","text":"Describe mitosis as nuclear division giving rise to genetically identical cells (details of the stages of mitosis are not required)"},{"n":"2","text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"},{"n":"3","text":"State that the exact replication of chromosomes occurs before mitosis"},{"n":"4","text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number in each daughter cell"},{"n":"5","text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.3","title":"Meiosis","core":[],"supplement":[{"n":"1","text":"State that meiosis is involved in the production of gametes"},{"n":"2","text":"Describe meiosis as a reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of the stages of meiosis are not required)"}]},{"n":"17.4","title":"Monohybrid inheritance","core":[{"n":"1","text":"Describe inheritance as the transmission of genetic information from generation to generation"},{"n":"2","text":"Describe genotype as the genetic make-up of an organism and in terms of the alleles present"},{"n":"3","text":"Describe phenotype as the observable features of an organism"},{"n":"4","text":"Describe homozygous as having two identical alleles of a particular gene"},{"n":"5","text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"n":"6","text":"Describe heterozygous as having two different alleles of a particular gene"},{"n":"7","text":"State that a heterozygous individual will not be pure-breeding"},{"n":"8","text":"Describe a dominant allele as an allele that is expressed if it is present in the genotype"},{"n":"9","text":"Describe a recessive allele as an allele that is only expressed when there is no dominant allele of the gene present in the genotype"},{"n":"10","text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"n":"11","text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1 : 1 and 3 : 1 ratios"},{"n":"12","text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"n":"13","text":"Explain how to use a test cross to identify an unknown genotype"},{"n":"14","text":"Describe codominance as a situation in which both alleles in heterozygous organisms contribute to the phenotype"},{"n":"15","text":"Explain the inheritance of ABO blood groups: phenotypes are A, B, AB and O blood groups and alleles are IA, IB and Io"},{"n":"16","text":"Describe a sex-linked characteristic as a feature in which the gene responsible is located on a sex chromosome and that this makes the characteristic more common in one sex than in the other"},{"n":"17","text":"Describe red-green colour blindness as an example of sex linkage"},{"n":"18","text":"Use genetic diagrams to predict the results of monohybrid crosses involving codominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"n":"1","text":"Describe variation as differences between individuals of the same species"},{"n":"2","text":"State that continuous variation results in a range of phenotypes between two extremes; examples include body length and body mass"},{"n":"3","text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates; examples include ABO blood groups, seed shape in peas and seed colour in peas"},{"n":"4","text":"State that discontinuous variation is usually caused by genes only and continuous variation is caused by both genes and the environment"},{"n":"5","text":"Investigate and describe examples of continuous and discontinuous variation"},{"n":"6","text":"Describe mutation as genetic change"},{"n":"7","text":"State that mutation is the way in which new alleles are formed"},{"n":"8","text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"n":"9","text":"Describe gene mutation as a random change in the base sequence of DNA"},{"n":"10","text":"State that mutation, meiosis, random mating and random fertilisation are sources of genetic variation in populations"}]},{"n":"18.2","title":"Adaptive features","core":[{"n":"1","text":"Describe an adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"n":"2","text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"n":"3","text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"n":"1","text":"Describe natural selection with reference to:\n(a) genetic variation within populations\n(b) production of many offspring\n(c) \u0007struggle for survival, including competition for resources\n(d) \u0007a greater chance of reproduction by individuals that are better adapted to the environment than others\n(e) \u0007these individuals pass on their alleles to the next generation"},{"n":"2","text":"Describe selective breeding with reference to:\n(a) \u0007selection by humans of individuals with desirable features\n(b) \u0007crossing these individuals to produce the next generation\n(c) \u0007selection of offspring showing the desirable features"},{"n":"3","text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals and apply this to given contexts"}],"supplement":[{"n":"4","text":"Describe adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"n":"5","text":"Describe the development of strains of antibiotic resistant bacteria as an example of natural selection"},{"n":"6","text":"Outline the differences between natural and artificial selection"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"n":"1","text":"State that the Sun is the principal source of energy input to biological systems"},{"n":"2","text":"Describe the flow of energy through living organisms, including light energy from the Sun and chemical energy in organisms, and its eventual transfer to the environment"}],"supplement":[]},{"n":"19.2","title":"Food chains and food webs","core":[{"n":"1","text":"Describe a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"n":"2","text":"Construct and interpret simple food chains"},{"n":"3","text":"Describe a food web as a network of interconnected food chains and interpret food webs"},{"n":"4","text":"Describe a producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"n":"5","text":"Describe a consumer as an organism that gets its energy by feeding on other organisms"},{"n":"6","text":"State that consumers may be classed as primary, secondary, tertiary and quaternary according to their position in a food chain"},{"n":"7","text":"Describe a herbivore as an animal that gets its energy by eating plants"},{"n":"8","text":"Describe a carnivore as an animal that gets its energy by eating other animals"},{"n":"9","text":"Describe a decomposer as an organism that gets its energy from dead or waste organic material"},{"n":"10","text":"Use food chains and food webs to describe the impact humans have through overharvesting of food species and through introducing foreign species to a habitat"},{"n":"11","text":"Draw, describe and interpret pyramids of numbers and pyramids of biomass"},{"n":"12","text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"},{"n":"13","text":"Describe a trophic level as the position of an organism in a food chain, food web or ecological pyramid"},{"n":"14","text":"Identify the following as the trophic levels in food webs, food chains and ecological pyramids: producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers"}],"supplement":[{"n":"15","text":"Draw, describe and interpret pyramids of energy"},{"n":"16","text":"Discuss the advantages of using a pyramid of energy rather than pyramids of numbers or biomass to represent a food chain"},{"n":"17","text":"Explain why the transfer of energy from one trophic level to another is often not efficient"},{"n":"18","text":"Explain, in terms of energy loss, why food chains usually have fewer than five trophic levels"},{"n":"19","text":"Explain why it is more energy efficient for humans to eat crop plants than to eat livestock that have been fed on crop plants"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"n":"1","text":"Describe the carbon cycle, limited to: photosynthesis, respiration, feeding, decomposition, formation of fossil fuels and combustion"}],"supplement":[{"n":"2","text":"Describe the nitrogen cycle with reference to: • decomposition of plant and animal protein to ammonium ions • nitrification • nitrogen fixation by lightning and bacteria • absorption of nitrate ions by plants • production of amino acids and proteins • feeding and digestion of proteins • deamination • denitrification"},{"n":"3","text":"State the roles of microorganisms in the nitrogen cycle, limited to: decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Populations","core":[{"n":"1","text":"Describe a population as a group of organisms of one species, living in the same area, at the same time"},{"n":"2","text":"Describe a community as all of the populations of different species in an ecosystem"},{"n":"3","text":"Describe an ecosystem as a unit containing the community of organisms and their environment, interacting together"},{"n":"4","text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, competition, predation and disease"},{"n":"5","text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid curve of population growth for a population growing in an environment with limited resources"},{"n":"6","text":"Interpret graphs and diagrams of population growth"}],"supplement":[{"n":"7","text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Human influences on ecosystems","sections":[{"n":"20.1","title":"Food supply","core":[{"n":"1","text":"Describe how humans have increased food production, limited to:\n(a) \u0007agricultural machinery to use larger areas of land and improve efficiency\n(b) chemical fertilisers to improve yields\n(c) insecticides to improve quality and yield\n(d) herbicides to reduce competition with weeds\n(e) \u0007selective breeding to improve production by crop plants and livestock"},{"n":"2","text":"Describe the advantages and disadvantages of large-scale monocultures of crop plants"},{"n":"3","text":"Describe the advantages and disadvantages of intensive livestock production"}],"supplement":[]},{"n":"20.2","title":"Habitat destruction","core":[{"n":"1","text":"Describe biodiversity as the number of different species that live in an area"},{"n":"2","text":"Describe the reasons for habitat destruction, including:\n(a) \u0007increased area for housing, crop plant production and livestock production\n(b) extraction of natural resources\n(c) freshwater and marine pollution"},{"n":"3","text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"n":"4","text":"Explain the undesirable effects of deforestation as an example of habitat destruction, to include: reducing biodiversity, extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[]},{"n":"20.3","title":"Pollution","core":[{"n":"1","text":"Describe the effects of untreated sewage and excess fertiliser on aquatic ecosystems"},{"n":"2","text":"Describe the effects of non-biodegradable plastics, in both aquatic and terrestrial ecosystems"},{"n":"3","text":"Describe the sources and effects of pollution of the air by methane and carbon dioxide, limited to: the enhanced greenhouse effect and climate change"}],"supplement":[{"n":"4","text":"Explain the process of eutrophication of water, limited to: • increased availability of nitrate and other ions • increased growth of producers • increased decomposition after death of producers • increased aerobic respiration by decomposers • reduction in dissolved oxygen • death of organisms requiring dissolved oxygen in water"}]},{"n":"20.4","title":"Conservation","core":[{"n":"1","text":"Describe a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"n":"2","text":"State that some resources can be conserved and managed sustainably, limited to forests and fish stocks"},{"n":"3","text":"Explain why organisms become endangered or extinct, including: climate change, habitat destruction, hunting, overharvesting, pollution and introduced species"},{"n":"4","text":"Describe how endangered species can be conserved, limited to:\n(a) \u0007monitoring and protecting species and habitats\n(b) education\n(c) captive breeding programmes\n(d) seed banks"}],"supplement":[{"n":"5","text":"Explain how forests can be conserved using: education, protected areas, quotas and replanting"},{"n":"6","text":"Explain how fish stocks can be conserved using: education, closed seasons, protected areas, controlled net types and mesh size, quotas and monitoring"},{"n":"7","text":"Describe the reasons for conservation programmes, limited to:\n(a) maintaining or increasing biodiversity\n(b) reducing extinction\n(c) protecting vulnerable ecosystems\n(d) \u0007maintaining ecosystem functions, limited to nutrient cycling and resource provision, including food, drugs, fuel and genes"},{"n":"8","text":"Describe the use of artificial insemination (AI) and in vitro fertilisation (IVF) in captive breeding programmes"},{"n":"9","text":"Explain the risks to a species if its population size decreases, reducing genetic variation (knowledge of genetic drift is not required)"}]}]},{"n":"21","title":"Biotechnology and genetic modification","sections":[{"n":"21.1","title":"Biotechnology and genetic modification","core":[{"n":"1","text":"State that bacteria are useful in biotechnology and genetic modification due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"n":"2","text":"Discuss why bacteria are useful in biotechnology and genetic modification, limited to:\n(a) \u0007few ethical concerns over their manipulation and growth\n(b) \u0007the presence of plasmids"}]},{"n":"21.2","title":"Biotechnology","core":[{"n":"1","text":"Describe the role of anaerobic respiration in yeast during the production of ethanol for biofuels"},{"n":"2","text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"n":"3","text":"Describe the use of pectinase in fruit juice production"},{"n":"4","text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"n":"5","text":"Explain the use of lactase to produce lactose-free milk"},{"n":"6","text":"Describe how fermenters can be used for the large-scale production of useful products by bacteria and fungi, including insulin, penicillin and mycoprotein"},{"n":"7","text":"Describe and explain the conditions that need to be controlled in a fermenter, including: temperature, pH, oxygen, nutrient supply and waste products"}]},{"n":"21.3","title":"Genetic modification","core":[{"n":"1","text":"Describe genetic modification as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"n":"2","text":"Outline examples of genetic modification:\n(a) \u0007the insertion of human genes into bacteria to produce human proteins\n(b) \u0007the insertion of genes into crop plants to confer resistance to herbicides\n(c) \u0007the insertion of genes into crop plants to confer resistance to insect pests\n(d) \u0007the insertion of genes into crop plants to improve nutritional qualities"}],"supplement":[{"n":"3","text":"Outline the process of genetic modification using bacterial production of a human protein as an example, limited to:\n(a) \u0007isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n(b) \u0007cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n(c) \u0007insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n(d) \u0007insertion of recombinant plasmids into bacteria (specific details are not required)\n(e) \u0007multiplication of bacteria containing recombinant plasmids\n(f) \u0007expression in bacteria of the human gene to make the human protein"},{"n":"4","text":"Discuss the advantages and disadvantages of genetically modifying crops, including soya, maize and rice"}]}]}]}]};
